#include <bits/stdc++.h>
using namespace std;

class InputReader {
public:
    string readln() {
        string s;
        getline(cin, s);
        return s;
    }

    int readlnInt() {
        return stoi(readln());
    }

    long long readlnLong() {
        return stoll(readln());
    }

    double readlnDouble() {
        return stod(readln());
    }

    vector<string> readlnStrings() {
        string s = readln();
        stringstream ss(s);
        vector<string> res;
        string x;
        while (ss >> x) res.push_back(x);
        return res;
    }

    vector<int> readlnInts() {
        auto v = readlnStrings();
        vector<int> res;
        for (auto &x : v) res.push_back(stoi(x));
        return res;
    }

    vector<long long> readlnLongs() {
        auto v = readlnStrings();
        vector<long long> res;
        for (auto &x : v) res.push_back(stoll(x));
        return res;
    }

    vector<double> readlnDoubles() {
        auto v = readlnStrings();
        vector<double> res;
        for (auto &x : v) res.push_back(stod(x));
        return res;
    }
};

class Main {
public:
    void solve(InputReader &inp) {
        auto nk = inp.readlnInts();
        int n = nk[0], k = nk[1];
        auto a = inp.readlnInts();
        int lim = a[k - 1];
        int ans = 0;
        for (int x : a) {
            if (x > 0 && x >= lim) ans++;
        }
        cout << ans;
    }
};

int main(int argc, char* argv[]) {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    InputReader inp;
    Main().solve(inp);
    return 0;
}

